import{_ as e,o,c as a,a3 as r}from"./chunks/framework.CohJ1kFH.js";const g=JSON.parse('{"title":"Chapter 7.5A 官方实战项目","description":"","frontmatter":{},"headers":[],"relativePath":"Milvus/chapter7/7.5A-Milvus3.0官方实战项目.md","filePath":"Milvus/chapter7/7.5A-Milvus3.0官方实战项目.md","lastUpdated":1794981646000}'),s={name:"Milvus/chapter7/7.5A-Milvus3.0官方实战项目.md"};function d(n,t,i,h,c,l){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="chapter-7-5a-官方实战项目" tabindex="-1">Chapter 7.5A 官方实战项目 <a class="header-anchor" href="#chapter-7-5a-官方实战项目" aria-label="Permalink to &quot;Chapter 7.5A 官方实战项目&quot;">​</a></h1><p>第 7 章到 7.4 为止，我们把 3.0 的每个新特性单独看过一遍。7.5 是实战，分为AB两部分，A部分用于介绍和复现官方Demo，一个特性一个应用，B部分是用一套数据工程闭环串联知识点。阅读下方第一个表格，<strong>如果不感兴趣，可以直接跳过本章节（包括本章节的ipynb文件），看B部分的内容。</strong></p><p>学完 7.5A，你应该能对着任何&quot;用 3.0 新特性做检索应用&quot;的需求，说清它的 schema、函数、索引与查询形态；学完 7.5B，你应该能把这套东西放进一条真实的数据管线里。第 7 章到此收官。</p><h2 id="_7-5a-1-五个-demo" tabindex="-1">7.5A.1 五个 demo <a class="header-anchor" href="#_7-5a-1-五个-demo" aria-label="Permalink to &quot;7.5A.1 五个 demo&quot;">​</a></h2><p>官方 demo 仓库 <a href="https://github.com/zc277584121/milvus3-demos" target="_blank" rel="noreferrer">milvus3-demos</a></p><table tabindex="0"><thead><tr><th>#</th><th>Demo</th><th>使用的核心特性</th><th>简介</th><th>所需数据</th></tr></thead><tbody><tr><td>1</td><td>MinHash 近重复检测</td><td><code>MINHASH</code> 函数 + <code>MINHASH_LSH</code> 索引</td><td>不生成向量也能算&quot;相似度&quot;</td><td>36 篇短文</td></tr><tr><td>2</td><td>函数链重排</td><td><code>FunctionChain</code> + <code>FileResource</code> + XGBoost</td><td>向量召回做基础，业务特征在库内重排</td><td>240 商品</td></tr><tr><td>3</td><td>StructArray 父子混合</td><td><code>ARRAY&lt;STRUCT&gt;</code> 元素级向量</td><td>一行存&quot;视频+它的 18 个目标&quot;，一次查询三种答法</td><td>30 视频 × 540 观察</td></tr><tr><td>4</td><td>EmbeddingList 多向量</td><td>页内 patch 级检索 + <code>MAX_SIM_COSINE</code></td><td>一页切多个块各自嵌入，回答&quot;哪一页讲了这件事&quot;</td><td>NASA 手册 40 页</td></tr><tr><td>5</td><td>搜索聚合</td><td><code>SearchAggregation</code></td><td>检索结果服务端直接分面统计，前端拿桶不用拉全量</td><td>90 部电影</td></tr></tbody></table><p><strong>环境要求</strong>：复用第 7 章的Milvus v3.0.2。Demo 2/3/4/5 需要一个 OpenAI 兼容的<strong>嵌入 API</strong> ，在环境变量里准备：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EMB_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你的嵌入API密钥</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_7-5a-2-demo-1-·-minhash-近重复检测" tabindex="-1">7.5A.2 Demo 1 · MinHash 近重复检测 <a class="header-anchor" href="#_7-5a-2-demo-1-·-minhash-近重复检测" aria-label="Permalink to &quot;7.5A.2 Demo 1 · MinHash 近重复检测&quot;">​</a></h2><p><strong>它解决什么</strong>：判断&quot;这篇文档是不是那篇的抄袭/变体&quot;。传统向量检索靠语义，但&quot;复制粘贴改几个词&quot;的文档语义几乎不变、向量几乎相同——反而抓不出<strong>字面级</strong>的重复。MinHash 反过来：不看语义，只看字面 shingle 的重合率（Jaccard 相似度），而且<strong>全程在 Milvus 内部完成</strong>，不需要任何嵌入模型。</p><p><strong>notebook</strong>：<code>7.5A-01-MinHash近重复检测.ipynb</code>。</p><p><strong>官方在线地址</strong>：<a href="https://demos.milvus.io/minhash-near-duplicate" target="_blank" rel="noreferrer">https://demos.milvus.io/minhash-near-duplicate</a></p><h2 id="_7-5a-3-demo-2-·-函数链重排" tabindex="-1">7.5A.3 Demo 2 · 函数链重排 <a class="header-anchor" href="#_7-5a-3-demo-2-·-函数链重排" aria-label="Permalink to &quot;7.5A.3 Demo 2 · 函数链重排&quot;">​</a></h2><p><strong>它解决什么</strong>：纯向量排序只懂语义相似，不懂生意——好评多的、近期上架的、价格贴着心理价位的，理应更靠前。3.0 的 <strong>L0 Function Chain</strong> 把&quot;特征计算 + 模型打分&quot;搬进数据库：召回后服务端自动跑一条链，输出业务分。</p><p><strong>notebook</strong>：<code>7.5A-02-函数链重排.ipynb</code>。</p><p><strong>官方在线地址</strong>：<a href="https://demos.milvus.io/function-chain-rerank" target="_blank" rel="noreferrer">https://demos.milvus.io/function-chain-rerank</a></p><h2 id="_7-5a-4-demo-3-·-structarray" tabindex="-1">7.5A.4 Demo 3 · StructArray <a class="header-anchor" href="#_7-5a-4-demo-3-·-structarray" aria-label="Permalink to &quot;7.5A.4 Demo 3 · StructArray&quot;">​</a></h2><p><strong>它解决什么</strong>：行车记录仪一帧里有多个目标（卡车/行人/自行车），每个目标都有自己的描述和向量。老做法是拆两张表（视频表 + 目标表）再 join；3.0 的 <strong><code>ARRAY&lt;STRUCT&gt;</code></strong> 把 18 个子记录（各带自己的向量）直接嵌在视频行里，一次查询能分别问&quot;哪段视频整体最像&quot;和&quot;哪个具体目标最像&quot;。</p><p><strong>notebook</strong>：<code>7.5A-03-StructArray父子混合检索.ipynb</code>。</p><p><strong>官方在线地址</strong>：<a href="https://demos.milvus.io/structarray-search" target="_blank" rel="noreferrer">https://demos.milvus.io/structarray-search</a></p><h2 id="_7-5a-5-demo-4-·-embeddinglist" tabindex="-1">7.5A.5 Demo 4 · EmbeddingList <a class="header-anchor" href="#_7-5a-5-demo-4-·-embeddinglist" aria-label="Permalink to &quot;7.5A.5 Demo 4 · EmbeddingList&quot;">​</a></h2><p><strong>它解决什么</strong>：一份 356 页的手册，问&quot;利益相关方期望怎么变成技术需求？&quot;——整页压成一个向量会&quot;平均掉&quot;页内细节，答案页和相邻页分不开。做法：<strong>每页切成多个 patch，各自嵌入</strong>，一页 = 一组向量。查询时对每个候选页算&quot;query 与页内所有 patch 的最大相似度&quot;（MAX_SIM），谁页里有最贴的段落谁排前。</p><p><strong>notebook</strong>：<code>7.5A-04-EmbeddingList多向量检索.ipynb</code>。</p><p><strong>官方在线地址</strong>：<a href="https://demos.milvus.io/embedding-list" target="_blank" rel="noreferrer">https://demos.milvus.io/embedding-list</a></p><h2 id="_7-5a-6-demo-5-·-search-aggregation" tabindex="-1">7.5A.6 Demo 5 · Search Aggregation <a class="header-anchor" href="#_7-5a-6-demo-5-·-search-aggregation" aria-label="Permalink to &quot;7.5A.6 Demo 5 · Search Aggregation&quot;">​</a></h2><p><strong>它解决什么</strong>：电商/内容站的搜索页都有&quot;类型/年代/地区&quot;的facet卡片。老做法是把 top-K 全拉回应用里自己 groupby——K 大了传输和内存都疼。3.0 的 <strong><code>SearchAggregation</code></strong> 让 Milvus 在<strong>服务端</strong>边搜边分桶，一次请求返回：每个桶的 key、桶内命中总数、桶内 Top 命中。</p><p><strong>notebook</strong>：<code>7.5A-05-SearchAggregation分面聚合.ipynb</code>。 <strong>官方在线地址</strong>：<a href="https://demos.milvus.io/movie-discovery" target="_blank" rel="noreferrer">https://demos.milvus.io/movie-discovery</a></p>',27)])])}const u=e(s,[["render",d]]);export{g as __pageData,u as default};
